import{_ as i,l,o as e,c as s,v as r,p as d,x as o,d as n,i as p,S as h}from"./chunks/framework.InCnrqk-.js";const S=JSON.parse('{"title":"SBOM 与可复现构建","description":"","frontmatter":{"title":"SBOM 与可复现构建","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/sbom-reproducible-builds.md","filePath":"cs/sbom-reproducible-builds.md","lastUpdated":1789023840000}'),c={name:"cs/sbom-reproducible-builds.md"};function u(B,a,b,E,m,_){const t=l("Mermaid");return e(),s("div",null,[a[1]||(a[1]=r('<h1 id="sbom-与可复现构建" tabindex="-1">SBOM 与可复现构建 <a class="header-anchor" href="#sbom-与可复现构建" aria-label="Permalink to &quot;SBOM 与可复现构建&quot;">​</a></h1><div class="epigraph"><p>你跑的那份二进制，必须能回答「里面有哪些依赖、是不是宣称的那份源码编出来的」。SBOM 是清单；可复现构建让第三方复验哈希。</p><footer>—— NTIA/CISA 对 SBOM 的最小要素；Debian 可复现构建；Wheeler 对信任编译器的讨论</footer></div><h2 id="定位" tabindex="-1">定位 <a class="header-anchor" href="#定位" aria-label="Permalink to &quot;定位&quot;">​</a></h2><p>上一课<a href="/cs/browser-sandbox">浏览器沙箱</a>缩小运行时权限。缺口是<strong>产物从哪来</strong>：依赖与编译器。本课收清单与复现，不把供应链攻击写成操作手册。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>SolarWinds 一类事故说明签名过的更新仍可能背刺——点名机制：构建系统被插。SBOM：组件名与版本。可复现：同样源→同样哈希。缺口是工程合同，不是密码学新原语。</p><h3 id="时间戳与路径" tabindex="-1">时间戳与路径 <a class="header-anchor" href="#时间戳与路径" aria-label="Permalink to &quot;时间戳与路径&quot;">​</a></h3><p>不可复现常是嵌入时间、乱序、绝对路径。要规范化。</p><p><span class="marginnote">CISA SBOM。Reproducible Builds 项目。Ken Thompson 的信任信任攻击是极限：编译器自身。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对照：只锁版本号 vs 锁哈希 vs 复现。签名要在复现哈希上。下一课依赖混淆：名字空间抢注。</p>',12)),(e(),d(h,null,{default:o(()=>[p(t,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20SRC%5B%22%E6%BA%90%E4%B8%8E%E4%BE%9D%E8%B5%96%E5%93%88%E5%B8%8C%22%5D%20--%3E%20BUILD%5B%22%E8%A7%84%E8%8C%83%E5%8C%96%E6%9E%84%E5%BB%BA%22%5D%0A%20%20BUILD%20--%3E%20BIN%5B%22%E4%BA%A7%E7%89%A9%E5%93%88%E5%B8%8C%22%5D%0A%20%20SBOM%5B%22SBOM%22%5D%20--%3E%20INV%5B%22%E6%B8%85%E5%8D%95%E5%8F%AF%E5%AE%A1%E8%AE%A1%22%5D%0A%20%20BIN%20--%3E%20SIG%5B%22%E7%AD%BE%E5%90%8D%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<p>图中节点是本课的机制骨架；课程不把图展开成可运行的攻击步骤。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>完整性要从运行时收到构建时。下一课依赖混淆：包管理器如何把名字解析到错误发布者。</p><p>前提写进合同之后，游戏外的误用只当失败模式点名，不在本课写成操作程序。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写投毒构建农场的步骤。依赖混淆下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>沙箱不管你编进了谁的库。</li><li>SBOM 列组件；可复现复验哈希。</li><li>签名应钉复现产物。</li><li>下一课依赖混淆。</li><li>出处：CISA/NTIA SBOM；Reproducible Builds；Thompson, Reflections on Trusting Trust。</li></ul>',8))])}const f=i(c,[["render",u]]);export{S as __pageData,f as default};
